interface ImageDisplayProps {
  url: string;
  loading: boolean;
  onRefresh: () => void;
}

const ImageDisplay: React.FC<ImageDisplayProps> = ({ url, loading, onRefresh }) => {
  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `kreativai-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
