import React, { useState, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import FeatureCard from './components/FeatureCard';
import ImageDisplay from './components/ImageDisplay';
import ApiKeyWall from './components/ApiKeyWall';
import { AppView, ImageStyle, AspectRatio, ImageSize } from './types';
import { FEATURES } from './constants';
import { generateImage, editImage, hasApiKey } from './services/geminiService';
import { Sparkles, Upload, Wand2, Plus, Trash2, Camera } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [needsApiKey, setNeedsApiKey] = useState(false);
  const [loading, setLoading] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ImageStyle>(ImageStyle.REALISTIC);
  const [ratio, setRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [size, setSize] = useState<ImageSize>(ImageSize.K1);
  const [brandName, setBrandName] = useState('');
  const [instruction, setInstruction] = useState('');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    checkKey();
  }, []);

  const checkKey = async () => {
    const hasKey = await hasApiKey();
    setNeedsApiKey(!hasKey);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetState = () => {
    setResultImage(null);
    setPrompt('');
    setInstruction('');
    setUploadedImage(null);
    setError(null);
  };

  const handleNavigate = (view: AppView) => {
    setCurrentView(view);
    resetState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      let finalPrompt = prompt;

      // Feature specific prompt engineering
      if (currentView === 'logo') {
        finalPrompt = `Professional logo design for brand named "${brandName}". Style: ${style}. Minimalist, high resolution, vector style. ${prompt}`;
      } else if (currentView === 'mascot') {
        finalPrompt = `Character mascot design. Expression: ${instruction}. Style: ${style}. Full body character on clean background. ${prompt}`;
      } else if (currentView === 'thumbnail') {
        finalPrompt = `Youtube thumbnail background and design with bold text "${brandName}". High contrast, eye catching. Style: ${style}. ${prompt}`;
      } else {
        finalPrompt = `${prompt}, style: ${style}`;
      }

      const url = await generateImage(finalPrompt, ratio, size);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("404") || err.message.includes("not found")) {
        setNeedsApiKey(true);
      }
      setError("Gagal memproses permintaan. Pastikan deskripsi jelas atau coba lagi nanti.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!uploadedImage) return;
    setLoading(true);
    setError(null);
    try {
      let editInstruction = instruction;

      if (currentView === 'graduation') {
        editInstruction = `Edit this person to wear a formal graduation toga and cap. Change the background to a beautiful university campus setting. Professional studio lighting. ${instruction}`;
      } else if (currentView === 'age') {
        editInstruction = `Modify the age of the person in the image. ${instruction}. Keep it realistic and natural.`;
      } else if (currentView === 'home') {
        editInstruction = `Cleanly remove ${instruction} from this image and fill the background naturally.`;
      }

      const url = await editImage(uploadedImage, editInstruction);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      setError("Gagal mengedit gambar. Pastikan gambar jelas dan instruksi spesifik.");
    } finally {
      setLoading(false);
    }
  };

  const isEditorView = ['edit', 'graduation', 'age', 'home'].includes(currentView);

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {needsApiKey && <ApiKeyWall onSuccess={() => setNeedsApiKey(false)} />}

      <Sidebar currentView={currentView} onNavigate={handleNavigate} />

      <main className="flex-1 lg:ml-64 p-4 lg:p-8">
        <header className="mb-10 max-w-6xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest mb-2">
              <Sparkles className="w-4 h-4" />
              Gemini Powered AI
            </div>
            <h1 className="text-4xl lg:text-5xl font-extrabold text-gray-900 tracking-tight">
              {currentView === 'home' ? 'Pusat Kreativitas AI' : FEATURES.find(f => f.id === currentView)?.title}
            </h1>
            <p className="text-gray-500 mt-3 text-lg max-w-xl leading-relaxed">
              {currentView === 'home' 
                ? 'Platform all-in-one untuk kebutuhan visual Anda. Dari logo profesional hingga pengeditan foto wisuda otomatis.'
                : FEATURES.find(f => f.id === currentView)?.description}
            </p>
          </div>
          {currentView !== 'home' && (
            <button 
              onClick={() => handleNavigate('home')}
              className="text-gray-500 hover:text-gray-900 font-semibold flex items-center gap-2 transition-colors px-4 py-2 bg-white rounded-xl border border-gray-200 shadow-sm"
            >
              Kembali ke Menu
            </button>
          )}
        </header>

        {currentView === 'home' ? (
          <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-20">
            {FEATURES.map((feature) => (
              <FeatureCard 
                key={feature.id} 
                feature={feature} 
                onClick={() => handleNavigate(feature.id)} 
              />
            ))}
          </div>
        ) : (
          <div className="max-w-6xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-10">
            {/* Form Side */}
            <div className="xl:col-span-7 space-y-8">
              <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-8">
                {isEditorView ? (
                  <div className="space-y-6">
                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Unggah Foto</span>
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="border-2 border-dashed border-gray-200 rounded-2xl p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50/30 transition-all group"
                      >
                        {uploadedImage ? (
                          <div className="relative inline-block">
                            <img src={uploadedImage} alt="Uploaded" className="max-h-64 rounded-xl shadow-lg" />
                            <button 
                              onClick={(e) => { e.stopPropagation(); setUploadedImage(null); }}
                              className="absolute -top-2 -right-2 bg-red-500 text-white p-2 rounded-full shadow-lg hover:scale-110 transition-transform"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        ) : (
                          <div className="flex flex-col items-center gap-4 py-4">
                            <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-blue-500 transition-colors">
                              <Upload className="w-8 h-8" />
                            </div>
                            <div>
                              <p className="font-bold text-gray-900">Ketuk untuk pilih gambar</p>
                              <p className="text-sm text-gray-500 mt-1">PNG, JPG atau WebP (Maks. 5MB)</p>
                            </div>
                          </div>
                        )}
                        <input 
                          type="file" 
                          ref={fileInputRef} 
                          onChange={handleImageUpload} 
                          className="hidden" 
                          accept="image/*" 
                        />
                      </div>
                    </label>

                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">
                        {currentView === 'home' ? 'Apa yang ingin dihapus?' : 
                         currentView === 'graduation' ? 'Instruksi Tambahan (Opsional)' :
                         currentView === 'age' ? 'Instruksi Usia (Contoh: "Jadikan umur 5 tahun")' :
                         'Apa yang ingin diubah?'}
                      </span>
                      <textarea
                        value={instruction}
                        onChange={(e) => setInstruction(e.target.value)}
                        placeholder="Contoh: Tambahkan senyum, hapus tong sampah, jadikan umur 60 tahun..."
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all h-32 text-gray-800 placeholder:text-gray-400"
                      />
                    </label>

                    <button
                      onClick={handleEdit}
                      disabled={loading || !uploadedImage}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 transition-all shadow-lg shadow-blue-200 active:scale-[0.98]"
                    >
