import React from 'react';

export type AppView = 'home' | 'generate' | 'edit' | 'logo' | 'mascot' | 'collage' | 'graduation' | 'thumbnail' | 'watermark' | 'age';

export enum ImageStyle {
  REALISTIC = 'Realistis',
  CARTOON = 'Kartun',
  ANIME = 'Anime',
  ILLUSTRATION = 'Ilustrasi',
  FLAT_DESIGN = 'Flat Design'
}

export enum AspectRatio {
  SQUARE = '1:1',
  LANDSCAPE = '16:9',
  PORTRAIT = '9:16',
  THREE_FOUR = '3:4',
  FOUR_THREE = '4:3'
}

export enum ImageSize {
  K1 = '1K',
  K2 = '2K',
  K4 = '4K'
}

export interface Feature {
  id: AppView;
  title: string;
  description: string;
  // Fixed: Added React import above to resolve React.ReactNode
  icon: React.ReactNode;
  color: string;
