  // Form states
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ImageStyle>(ImageStyle.REALISTIC);
  const [ratio, setRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [brandName, setBrandName] = useState('');
  const [instruction, setInstruction] = useState('');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [watermark, setWatermark] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetState = () => {
    setResultImage(null);
    setPrompt('');
    setInstruction('');
    setUploadedImage(null);
    setError(null);
    setWatermark('');
  };

  const handleNavigate = (view: AppView) => {
    setCurrentView(view);
    resetState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      let finalPrompt = prompt;

      if (currentView === 'logo') {
        finalPrompt = `Modern professional logo for "${brandName}". Style: ${style}. Minimalist vector. ${prompt}`;
      } else if (currentView === 'mascot') {
        finalPrompt = `Unique mascot character. Expression: ${instruction}. Style: ${style}. High detail, white background. ${prompt}`;
      } else if (currentView === 'thumbnail') {
        finalPrompt = `Stunning YouTube thumbnail for "${brandName}". Bold text, high contrast. Style: ${style}. ${prompt}`;
      } else {
        finalPrompt = `${prompt}, in ${style} style.`;
      }

      const url = await generateImage(finalPrompt, ratio);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      setError("Ups! Terjadi kesalahan. Coba deskripsi yang lebih sederhana.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!uploadedImage) return;
    setLoading(true);
    setError(null);
    try {
      let editInstruction = instruction;

      if (currentView === 'graduation') {
        editInstruction = `Transform the person in this photo to wear a high-quality graduation toga and cap. Background should be a campus or studio. ${instruction}`;
      } else if (currentView === 'age') {
        editInstruction = `Change the age of the person in this photo. ${instruction}. Realistic and natural features.`;
      } else if (currentView === 'home') {
        editInstruction = `Remove ${instruction} from this image and fill the gap naturally.`;
      } else if (currentView === 'edit') {
        editInstruction = instruction;
      }

      const url = await editImage(uploadedImage, editInstruction);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      setError("Gagal mengolah foto. Pastikan wajah atau objek terlihat jelas.");
    } finally {
      setLoading(false);
    }
  };

