              <ImageIcon className="w-10 h-10" />
            </div>
            <p className="text-sm font-semibold text-gray-400">Pratinjau Hasil</p>
            <p className="text-xs mt-2 text-gray-400">Karya Anda akan muncul di sini setelah diproses.</p>
          </div>
        )}
      </div>

      {url && !loading && (
        <div className="p-6 bg-gray-50 border-t border-gray-100 flex items-center justify-between gap-4">
          <button
            onClick={handleDownload}
            className="flex-1 bg-white hover:bg-gray-100 text-gray-900 border border-gray-200 py-3 rounded-xl flex items-center justify-center gap-2 font-semibold transition-all shadow-sm"
          >
            <Download className="w-5 h-5" />
            Simpan Gambar
          </button>
          <button
            onClick={() => {
              if (navigator.share) {
                navigator.share({ title: 'Dibuat dengan KreativAI', url });
              }
            }}
            className="w-12 h-12 bg-white hover:bg-gray-100 border border-gray-200 rounded-xl flex items-center justify-center transition-all shadow-sm"
            title="Bagikan"
          >
            <Share2 className="w-5 h-5 text-gray-600" />
          </button>
          <button
            onClick={onRefresh}
            className="w-12 h-12 bg-blue-600 hover:bg-blue-700 rounded-xl flex items-center justify-center transition-all shadow-lg shadow-blue-200"
            title="Coba Lagi"
          >
            <RefreshCw className="w-5 h-5 text-white" />
          </button>
        </div>
      )}
    </div>
  );
};

