import { GoogleGenAI } from "@google/genai";
import { AspectRatio } from "../types";

const getAI = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateImage = async (
  prompt: string, 
  aspectRatio: AspectRatio = AspectRatio.SQUARE
): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mendapatkan gambar dari AI");
};

export const editImage = async (
  base64Image: string,
  instruction: string,
  mimeType: string = 'image/png'
): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        { text: instruction },
      ],
    },
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mengedit gambar");
};

export const createCollage = async (
  base64Images: string[],
  instruction: string = "Create a stylish and artistic photo collage using these 4 images."
): Promise<string> => {
  const ai = getAI();
  const parts: any[] = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/png'
    }
  }));

  parts.push({ text: instruction });

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal membuat kolase");
};

import React, { useState, useRef } from 'react';
import Sidebar from './components/Sidebar';
import FeatureCard from './components/FeatureCard';
import ImageDisplay from './components/ImageDisplay';
import { AppView, ImageStyle, AspectRatio } from './types';
import { FEATURES } from './constants';
import { generateImage, editImage, createCollage } from './services/geminiService';
import { Sparkles, Upload, Wand2, Plus, Trash2, Type, LayoutGrid } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [loading, setLoading] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ImageStyle>(ImageStyle.REALISTIC);
  const [ratio, setRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [brandName, setBrandName] = useState('');
  const [instruction, setInstruction] = useState('');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [collageImages, setCollageImages] = useState<(string | null)[]>([null, null, null, null]);
  const [watermark, setWatermark] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const collageInputRefs = [useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null)];

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCollageUpload = (index: number, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newImages = [...collageImages];
        newImages[index] = reader.result as string;
        setCollageImages(newImages);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetState = () => {
    setResultImage(null);
    setPrompt('');
    setInstruction('');
    setUploadedImage(null);
    setCollageImages([null, null, null, null]);
    setError(null);
    setWatermark('');
  };

  const handleNavigate = (view: AppView) => {
    setCurrentView(view);
    resetState();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      if (currentView === 'collage') {
        const validImages = collageImages.filter(img => img !== null) as string[];
        if (validImages.length < 2) throw new Error("Unggah minimal 2 gambar untuk membuat kolase.");
        const url = await createCollage(validImages, instruction || "Create a beautiful artistic photo collage from these images.");
        setResultImage(url);
        return;
      }

      let finalPrompt = prompt;
      if (currentView === 'logo') {
        finalPrompt = `Modern professional logo for "${brandName}". Style: ${style}. Minimalist vector. ${prompt}`;
      } else if (currentView === 'mascot') {
        finalPrompt = `Unique mascot character. Expression: ${instruction}. Style: ${style}. High detail, white background. ${prompt}`;
      } else if (currentView === 'thumbnail') {
        finalPrompt = `Stunning YouTube thumbnail for "${brandName}". Bold text, high contrast. Style: ${style}. ${prompt}`;
      } else {
        finalPrompt = `${prompt}, in ${style} style.`;
      }

      const url = await generateImage(finalPrompt, ratio);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Ups! Terjadi kesalahan. Coba lagi.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!uploadedImage) return;
    setLoading(true);
    setError(null);
    try {
      let editInstruction = instruction;

      if (currentView === 'graduation') {
        editInstruction = `Transform the person in this photo to wear a high-quality graduation toga and cap. Background should be a university campus or studio. ${instruction}`;
      } else if (currentView === 'age') {
        editInstruction = `Change the age of the person in this photo. ${instruction}. Realistic and natural features.`;
      } else if (currentView === 'remove-object') {
        editInstruction = `Cleanly remove the ${instruction} from this image and fill the gap naturally based on the surroundings.`;
      } else if (currentView === 'edit') {
        editInstruction = instruction;
      }

      const url = await editImage(uploadedImage, editInstruction);
      setResultImage(url);
    } catch (err: any) {
      console.error(err);
      setError("Gagal mengolah foto. Pastikan objek terlihat jelas.");
    } finally {
      setLoading(false);
    }
  };

  const isEditorView = ['edit', 'graduation', 'age', 'remove-object'].includes(currentView);
  const isCollageView = currentView === 'collage';

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar currentView={currentView} onNavigate={handleNavigate} />

      <main className="flex-1 lg:ml-64 p-4 lg:p-8">
        <header className="mb-10 max-w-6xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest mb-2">
              <Sparkles className="w-4 h-4" />
              KreativAI Engine v2.5
            </div>
            <h1 className="text-4xl lg:text-5xl font-extrabold text-gray-900 tracking-tight">
              {currentView === 'home' ? 'Pusat Kreativitas' : FEATURES.find(f => f.id === currentView)?.title}
            </h1>
            <p className="text-gray-500 mt-3 text-lg max-w-xl leading-relaxed">
              {currentView === 'home' 
                ? 'Solusi AI pengolah gambar instan untuk UMKM, pelajar, dan konten kreator.'
                : FEATURES.find(f => f.id === currentView)?.description}
            </p>
          </div>
          {currentView !== 'home' && (
            <button 
              onClick={() => handleNavigate('home')}
              className="text-gray-500 hover:text-gray-900 font-semibold flex items-center gap-2 transition-colors px-4 py-2 bg-white rounded-xl border border-gray-200 shadow-sm"
            >
              Menu Utama
            </button>
          )}
        </header>

        {currentView === 'home' ? (
          <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-20">
            {FEATURES.map((feature) => (
              <FeatureCard 
                key={feature.id} 
                feature={feature} 
                onClick={() => handleNavigate(feature.id)} 
              />
            ))}
          </div>
        ) : (
          <div className="max-w-6xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-10">
            {/* Form Side */}
            <div className="xl:col-span-7 space-y-8">
              <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-8">

                {isCollageView ? (
                  <div className="space-y-6">
                    <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Pilih 4 Gambar untuk Kolase</span>
                    <div className="grid grid-cols-2 gap-4">
                      {collageImages.map((img, idx) => (
                        <div 
                          key={idx}
                          onClick={() => collageInputRefs[idx].current?.click()}
                          className="aspect-square border-2 border-dashed border-gray-200 rounded-2xl flex items-center justify-center cursor-pointer hover:border-blue-500 hover:bg-blue-50/30 transition-all overflow-hidden relative group"
                        >
                          {img ? (
                            <>
                              <img src={img} className="w-full h-full object-cover" alt={`Collage ${idx}`} />
                              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Plus className="text-white w-8 h-8" />
                              </div>
                            </>
                          ) : (
                            <Plus className="text-gray-300 w-10 h-10" />
                          )}
                          <input type="file" ref={collageInputRefs[idx]} onChange={(e) => handleCollageUpload(idx, e)} className="hidden" accept="image/*" />
                        </div>
                      ))}
                    </div>

                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Instruksi Kolase (Opsional)</span>
                      <textarea
                        value={instruction}
                        onChange={(e) => setInstruction(e.target.value)}
                        placeholder="Contoh: Buat dengan gaya minimalis dengan border putih tipis..."
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-24"
                      />
                    </label>

                    <button
                      onClick={handleGenerate}
                      disabled={loading || collageImages.filter(i => i).length < 2}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 transition-all shadow-lg active:scale-[0.98]"
                    >
                      <LayoutGrid className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                      {loading ? 'Menyusun Kolase...' : 'Buat Kolase Sekarang'}
                    </button>
                  </div>
                ) : isEditorView ? (
                  <div className="space-y-6">
                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Pilih Foto Anda</span>
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="border-2 border-dashed border-gray-200 rounded-2xl p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50/30 transition-all group"
                      >
                        {uploadedImage ? (
                          <div className="relative inline-block">
                            <img src={uploadedImage} alt="Uploaded" className="max-h-64 rounded-xl shadow-lg" />
                            <button 
                              onClick={(e) => { e.stopPropagation(); setUploadedImage(null); }}
                              className="absolute -top-2 -right-2 bg-red-500 text-white p-2 rounded-full shadow-lg"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        ) : (
                          <div className="flex flex-col items-center gap-4 py-4">
                            <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-blue-500 transition-colors">
                              <Upload className="w-8 h-8" />
                            </div>
                            <div>
                              <p className="font-bold text-gray-900">Klik untuk upload foto</p>
                              <p className="text-sm text-gray-500 mt-1">PNG atau JPG (Maks. 5MB)</p>
                            </div>
                          </div>
                        )}
                        <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                      </div>
                    </label>

                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">
                        {currentView === 'remove-object' ? 'Objek Apa yang Ingin Dihapus?' : 'Instruksi AI'}
                      </span>
                      <textarea
                        value={instruction}
                        onChange={(e) => setInstruction(e.target.value)}
                        placeholder={currentView === 'remove-object' ? "Contoh: Orang di latar belakang, tiang listrik, tong sampah..." : "Apa yang ingin diubah?"}
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all h-32 text-gray-800"
                      />
                    </label>

                    <button
                      onClick={handleEdit}
                      disabled={loading || !uploadedImage}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 transition-all shadow-lg active:scale-[0.98]"
