                  </div>
                ) : (
                  <div className="space-y-6">
                    {(currentView === 'logo' || currentView === 'thumbnail') && (
                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Nama Brand / Judul Utama</span>
                        <input
                          type="text"
                          value={brandName}
                          onChange={(e) => setBrandName(e.target.value)}
                          placeholder="Contoh: Kedai Digital / 5 Tips Sukses"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all text-gray-800"
