                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Deskripsi Gambar (Prompt)</span>
                      <textarea
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Contoh: Pemandangan gunung dengan kabut pagi, sinematik..."
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all h-32 text-gray-800"
                      />
                    </label>

                    <div className="grid grid-cols-2 gap-6">
                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Gaya Visual</span>
                        <select
                          value={style}
                          onChange={(e) => setStyle(e.target.value as ImageStyle)}
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all text-gray-800"
                        >
                          {Object.values(ImageStyle).map((s) => (
                            <option key={s} value={s}>{s}</option>
                          ))}
                        </select>
                      </label>

                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Format Ukuran</span>
                        <select
                          value={ratio}
                          onChange={(e) => setRatio(e.target.value as AspectRatio)}
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all text-gray-800"
                        >
                          <option value={AspectRatio.SQUARE}>Square (1:1)</option>
                          <option value={AspectRatio.LANDSCAPE}>Landscape (16:9)</option>
                          <option value={AspectRatio.PORTRAIT}>Portrait (9:16)</option>
                        </select>
                      </label>
                    </div>

                    <button
                      onClick={handleGenerate}
                      disabled={loading || (!prompt && !brandName)}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 transition-all shadow-lg active:scale-[0.98]"
                    >
                      <Sparkles className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                      {loading ? 'AI Sedang Bekerja...' : 'Buat Sekarang'}
                    </button>
                  </div>
                )}

                {error && (
                  <div className="mt-4 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
                    {error}
                  </div>
                )}
              </div>
            </div>

            {/* Preview Side */}
            <div className="xl:col-span-5 relative">
              <ImageDisplay 
                url={resultImage || ''} 
                loading={loading} 
                onRefresh={isEditorView ? handleEdit : handleGenerate} 
              />
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

