        { x: halfSize + spacing, y: 0 },
        { x: 0, y: halfSize + spacing },
        { x: halfSize + spacing, y: halfSize + spacing }
      ];

      images.forEach((src, idx) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
          const pos = positions[idx];

          // Kalkulasi aspect fill (cover)
          const imgRatio = img.width / img.height;
          let drawW, drawH, offsetLeft, offsetTop;

          if (imgRatio > 1) { // Landscape
            drawH = halfSize;
            drawW = halfSize * imgRatio;
            offsetLeft = (drawW - halfSize) / 2;
            offsetTop = 0;
          } else { // Portrait
            drawW = halfSize;
            drawH = halfSize / imgRatio;
            offsetLeft = 0;
            offsetTop = (drawH - halfSize) / 2;
          }

          ctx.save();
          // Membuat clipping area melengkung (rounded corners)
          const radius = 40;
          ctx.beginPath();
          ctx.moveTo(pos.x + radius, pos.y);
          ctx.lineTo(pos.x + halfSize - radius, pos.y);
          ctx.quadraticCurveTo(pos.x + halfSize, pos.y, pos.x + halfSize, pos.y + radius);
          ctx.lineTo(pos.x + halfSize, pos.y + halfSize - radius);
          ctx.quadraticCurveTo(pos.x + halfSize, pos.y + halfSize, pos.x + halfSize - radius, pos.y + halfSize);
          ctx.lineTo(pos.x + radius, pos.y + halfSize);
          ctx.quadraticCurveTo(pos.x, pos.y + halfSize, pos.x, pos.y + halfSize - radius);
          ctx.lineTo(pos.x, pos.y + radius);
          ctx.quadraticCurveTo(pos.x, pos.y, pos.x + radius, pos.y);
          ctx.closePath();
          ctx.clip();

          ctx.drawImage(img, pos.x - offsetLeft, pos.y - offsetTop, drawW, drawH);
          ctx.restore();

          loadedCount++;
          if (loadedCount === images.length) {
            resolve(canvas.toDataURL('image/png', 1.0));
          }
        };
        img.onerror = () => reject("Gagal memuat salah satu gambar");
        img.src = src;
      });
