                          >
                            <Eraser className="w-6 h-6" />
                            <span className="text-xs font-bold">Hapus Teks</span>
                          </button>
                          <button 
                            onClick={() => setWatermarkType('remove_logo')}
                            className={`p-4 rounded-2xl border flex flex-col items-center gap-2 transition-all ${watermarkType === 'remove_logo' ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-gray-200 hover:border-blue-300'}`}
                          >
                            <Zap className="w-6 h-6" />
                            <span className="text-xs font-bold">Hapus Logo</span>
                          </button>
                          <button 
                            onClick={() => setWatermarkType('upscale')}
                            className={`p-4 rounded-2xl border flex flex-col items-center gap-2 transition-all ${watermarkType === 'upscale' ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-gray-200 hover:border-blue-300'}`}
                          >
                            <Sparkles className="w-6 h-6" />
                            <span className="text-xs font-bold">Tingkatkan Kualitas</span>
                          </button>
                        </div>

                        {watermarkType === 'add' && (
                          <label className="block">
                            <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Teks Watermark</span>
                            <input
                              type="text"
