                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">
                          {currentView === 'remove-object' ? 'Objek yang ingin dihapus' : 'Instruksi Tambahan'}
                        </span>
                        <textarea
                          value={instruction}
                          onChange={(e) => setInstruction(e.target.value)}
                          placeholder={currentView === 'remove-object' ? "Contoh: Orang di belakang, tiang listrik, tong sampah..." : "Detail tambahan untuk AI..."}
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32"
                        />
                      </label>
                    )}

                    <button
                      onClick={handleEdit}
                      disabled={loading || !uploadedImage}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95"
                    >
                      <Wand2 className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                      {loading ? 'Memproses Gambar...' : 'Mulai Proses AI'}
                    </button>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {(currentView === 'logo' || currentView === 'thumbnail') && (
                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Teks Brand / Judul</span>
                        <input
                          type="text"
                          value={brandName}
                          onChange={(e) => setBrandName(e.target.value)}
                          placeholder="Nama yang akan ditampilkan di hasil..."
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                      </label>
                    )}

                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Deskripsi Gambar (Prompt)</span>
                      <textarea
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        placeholder="Contoh: Kucing astronot di bulan, gaya artistik digital..."
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32"
                      />
                    </label>

                    <div className="grid grid-cols-2 gap-6">
                      <div className="space-y-3">
                         <span className="text-sm font-bold text-gray-900 block uppercase tracking-wider">Gaya Visual</span>
                         <select value={style} onChange={(e) => setStyle(e.target.value as ImageStyle)} className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 outline-none">
                            {Object.values(ImageStyle).map(s => <option key={s} value={s}>{s}</option>)}
                         </select>
                      </div>
                      <div className="space-y-3">
                         <span className="text-sm font-bold text-gray-900 block uppercase tracking-wider">Ukuran</span>
                         <select value={ratio} onChange={(e) => setRatio(e.target.value as AspectRatio)} className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 outline-none">
                            <option value={AspectRatio.SQUARE}>Persegi (1:1)</option>
                            <option value={AspectRatio.LANDSCAPE}>Landscape (16:9)</option>
                            <option value={AspectRatio.PORTRAIT}>Portrait (9:16)</option>
                         </select>
                      </div>
                    </div>

                    <button
                      onClick={handleGenerate}
                      disabled={loading || !prompt}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95"
                    >
                      <Sparkles className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                      {loading ? 'AI Sedang Melukis...' : 'Hasilkan Gambar'}
                    </button>
                  </div>
                )}

                {error && <div className="mt-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-medium border border-red-100">{error}</div>}
              </div>
            </div>

            {/* Preview Side */}
            <div className="xl:col-span-5">
              <ImageDisplay 
                url={resultImage || ''} 
                loading={loading} 
                onRefresh={isEditorView ? handleEdit : handleGenerate} 
              />
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

