import React, { useState, useRef } from 'react';
import Sidebar from './components/Sidebar';
import FeatureCard from './components/FeatureCard';
import ImageDisplay from './components/ImageDisplay';
import { AppView, ImageStyle, AspectRatio } from './types';
import { FEATURES } from './constants';
import { generateImage, editImage } from './services/geminiService';
import { Sparkles, Upload, Wand2, Plus, Trash2, LayoutGrid, Info, Type, Eraser, Zap, ShieldAlert, Video } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [loading, setLoading] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ImageStyle>(ImageStyle.REALISTIC);
  const [ratio, setRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [brandName, setBrandName] = useState('');
  const [instruction, setInstruction] = useState('');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [collageImages, setCollageImages] = useState<(string | null)[]>([null, null, null, null]);
  const [watermarkAction, setWatermarkAction] = useState<'remove_text' | 'remove_logo' | 'upscale'>('remove_text');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const collageInputRefs = [useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null)];

  const createLocalCollage = async (images: string[]): Promise<string> => {
    return new Promise((resolve, reject) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return reject("Gagal menginisialisasi canvas");

      const size = 2000;
      const spacing = 40;
      const halfSize = (size - spacing) / 2;

      canvas.width = size;
      canvas.height = size;

      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, size, size);

      let loadedCount = 0;
      const positions = [
        { x: 0, y: 0 },
        { x: halfSize + spacing, y: 0 },
        { x: 0, y: halfSize + spacing },
        { x: halfSize + spacing, y: halfSize + spacing }
      ];

      images.forEach((src, idx) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => {
          const pos = positions[idx];
          const imgRatio = img.width / img.height;
          let drawW, drawH, offsetLeft, offsetTop;

          if (imgRatio > 1) {
            drawH = halfSize;
            drawW = halfSize * imgRatio;
            offsetLeft = (drawW - halfSize) / 2;
            offsetTop = 0;
          } else {
            drawW = halfSize;
            drawH = halfSize / imgRatio;
            offsetLeft = 0;
            offsetTop = (drawH - halfSize) / 2;
          }

          ctx.save();
          const radius = 40;
          ctx.beginPath();
          ctx.moveTo(pos.x + radius, pos.y);
          ctx.lineTo(pos.x + halfSize - radius, pos.y);
          ctx.quadraticCurveTo(pos.x + halfSize, pos.y, pos.x + halfSize, pos.y + radius);
          ctx.lineTo(pos.x + halfSize, pos.y + halfSize - radius);
          ctx.quadraticCurveTo(pos.x + halfSize, pos.y + halfSize, pos.x + halfSize - radius, pos.y + halfSize);
          ctx.lineTo(pos.x + radius, pos.y + halfSize);
          ctx.quadraticCurveTo(pos.x, pos.y + halfSize, pos.x, pos.y + halfSize - radius);
          ctx.lineTo(pos.x, pos.y + radius);
          ctx.quadraticCurveTo(pos.x, pos.y, pos.x + radius, pos.y);
          ctx.closePath();
          ctx.clip();

          ctx.drawImage(img, pos.x - offsetLeft, pos.y - offsetTop, drawW, drawH);
          ctx.restore();

          loadedCount++;
          if (loadedCount === images.length) {
            resolve(canvas.toDataURL('image/png', 1.0));
          }
        };
        img.onerror = () => reject("Gagal memuat salah satu gambar");
        img.src = src;
      });
    });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setUploadedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCollageUpload = (index: number, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newImages = [...collageImages];
        newImages[index] = reader.result as string;
        setCollageImages(newImages);
      };
      reader.readAsDataURL(file);
    }
  };

  const resetState = () => {
    setResultImage(null);
    setPrompt('');
    setInstruction('');
    setUploadedImage(null);
    setCollageImages([null, null, null, null]);
    setWatermarkAction('remove_text');
    setBrandName('');
    setError(null);
  };

  const handleNavigate = (view: AppView) => {
    setCurrentView(view);
    resetState();
    if (view === 'thumbnail') {
      setRatio(AspectRatio.LANDSCAPE); // Default untuk YouTube Thumbnail
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      if (currentView === 'collage') {
        const validImages = collageImages.filter(img => img !== null) as string[];
        if (validImages.length < 2) throw new Error("Unggah minimal 2 gambar untuk kolase.");
        const url = await createLocalCollage(validImages);
        setResultImage(url);
        return;
      }

      let finalPrompt = prompt;
      if (currentView === 'logo') {
        finalPrompt = `Professional vector logo for "${brandName}". Clean, high resolution. Style: ${style}. ${prompt}`;
      } else if (currentView === 'mascot') {
        finalPrompt = `Character mascot. Style: ${style}. Isolated on white. ${prompt}`;
      } else if (currentView === 'thumbnail') {
        finalPrompt = `Stunning YouTube thumbnail for a video titled "${brandName}". Background design: ${prompt}. High contrast, eye-catching text, style: ${style}.`;
      } else {
        finalPrompt = `${prompt}, ${style} style.`;
      }

      const url = await generateImage(finalPrompt, ratio);
      setResultImage(url);
    } catch (err: any) {
      setError(err.message || "Gagal memproses permintaan.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!uploadedImage) return;
    setLoading(true);
    setError(null);
    try {
      let editInstruction = instruction;

      if (currentView === 'watermark') {
        switch(watermarkAction) {
          case 'remove_text':
            editInstruction = `Remove all text watermarks and lettering from this image. Carefully inpaint the background to look original and clean.`;
            break;
          case 'remove_logo':
            editInstruction = `Detect and remove any logo watermarks or branding icons from this image. Fill the background space naturally.`;
            break;
          case 'upscale':
            editInstruction = `Sharpen this image, enhance details, and increase clarity. Reduce noise and make it look professional and high resolution.`;
            break;
        }
      } else if (currentView === 'remove-object') {
        editInstruction = `Remove the object: "${instruction}" from this photo. Use seamless inpainting to fill the background.`;
      } else if (currentView === 'graduation') {
        editInstruction = `Add a professional graduation toga and cap to the person in this photo. White/Studio background. ${instruction}`;
      } else if (currentView === 'age') {
        editInstruction = `Change the person's age: ${instruction}. Maintain facial structure and realism.`;
      } else {
        editInstruction = instruction;
      }

      const url = await editImage(uploadedImage, editInstruction);
      setResultImage(url);
    } catch (err: any) {
      setError("Ups! Gagal memproses gambar. Pastikan kualitas foto cukup baik.");
    } finally {
      setLoading(false);
    }
  };

  const isEditorView = ['edit', 'graduation', 'age', 'remove-object', 'watermark'].includes(currentView);
  const isCollageView = currentView === 'collage';

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar currentView={currentView} onNavigate={handleNavigate} />

      <main className="flex-1 lg:ml-64 p-4 lg:p-8">
        <header className="mb-10 max-w-6xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest mb-2">
              <Sparkles className="w-4 h-4" />
              Gemini KreativAI v2.5
            </div>
            <h1 className="text-4xl lg:text-5xl font-extrabold text-gray-900 tracking-tight">
              {currentView === 'home' ? 'Pusat Kreativitas AI' : FEATURES.find(f => f.id === currentView)?.title}
            </h1>
            <p className="text-gray-500 mt-3 text-lg max-w-xl leading-relaxed">
              {FEATURES.find(f => f.id === currentView)?.description}
            </p>
          </div>
          {currentView !== 'home' && (
            <button 
              onClick={() => handleNavigate('home')}
              className="text-gray-500 hover:text-gray-900 font-semibold flex items-center gap-2 transition-colors px-4 py-2 bg-white rounded-xl border border-gray-200 shadow-sm"
            >
              Menu Utama
            </button>
          )}
        </header>

        {currentView === 'home' ? (
          <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-20">
            {FEATURES.map((feature) => (
              <FeatureCard 
                key={feature.id} 
                feature={feature} 
                onClick={() => handleNavigate(feature.id)} 
              />
            ))}
          </div>
        ) : (
          <div className="max-w-6xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-10">
            {/* Form Side */}
            <div className="xl:col-span-7 space-y-8">
              <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-8">

                {isCollageView ? (
                  <div className="space-y-6">
                    <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex gap-3 text-blue-700 text-sm">
                      <Info className="w-5 h-5 shrink-0" />
                      <p>Gabungkan hingga 4 foto secara instan. Hasil akan mempertahankan kualitas asli foto Anda tanpa distorsi AI.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      {collageImages.map((img, idx) => (
                        <div 
                          key={idx}
                          onClick={() => collageInputRefs[idx].current?.click()}
                          className="aspect-square border-2 border-dashed border-gray-200 rounded-2xl flex items-center justify-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all overflow-hidden relative"
                        >
                          {img ? (
                            <img src={img} className="w-full h-full object-cover" alt="Preview" />
                          ) : (
                            <div className="flex flex-col items-center gap-2 text-gray-400">
                              <Plus className="w-8 h-8" />
                              <span className="text-xs font-bold">Slot {idx + 1}</span>
                            </div>
                          )}
                          <input type="file" ref={collageInputRefs[idx]} onChange={(e) => handleCollageUpload(idx, e)} className="hidden" accept="image/*" />
                        </div>
                      ))}
                    </div>

                    <button
                      onClick={handleGenerate}
                      disabled={loading || collageImages.filter(i => i).length < 2}
                      className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95"
                    >
                      <LayoutGrid className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                      {loading ? 'Menyusun Kolase...' : 'Gabungkan Sekarang'}
                    </button>
                  </div>
                ) : isEditorView ? (
                  <div className="space-y-6">
                    <label className="block">
                      <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Unggah Foto Utama</span>
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="border-2 border-dashed border-gray-200 rounded-2xl p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all"
                      >
                        {uploadedImage ? (
                          <div className="relative inline-block">
                            <img src={uploadedImage} alt="Uploaded" className="max-h-64 rounded-xl shadow-lg" />
                            <div className="absolute -top-2 -right-2 bg-blue-600 text-white p-1.5 rounded-full shadow-lg"><Upload className="w-4 h-4" /></div>
                          </div>
                        ) : (
                          <div className="flex flex-col items-center gap-4 py-4">
                            <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400">
                              <Upload className="w-8 h-8" />
                            </div>
                            <p className="font-bold text-gray-900">Ketuk untuk pilih foto</p>
                          </div>
                        )}
                        <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                      </div>
                    </label>

                    {currentView === 'watermark' ? (
                      <div className="space-y-6">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Pilih Alat Pembersih</span>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          <button 
                            onClick={() => setWatermarkAction('remove_text')}
                            className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'remove_text' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}
                          >
                            <Eraser className="w-8 h-8" />
                            <div className="text-center">
                              <span className="text-xs font-bold block">Hapus Teks</span>
                              <span className="text-[10px] opacity-60">Watermark Tulisan</span>
                            </div>
                          </button>
                          <button 
                            onClick={() => setWatermarkAction('remove_logo')}
                            className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'remove_logo' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}
                          >
                            <ShieldAlert className="w-8 h-8" />
                            <div className="text-center">
                              <span className="text-xs font-bold block">Hapus Logo</span>
                              <span className="text-[10px] opacity-60">Ikon / Branding</span>
                            </div>
                          </button>
                          <button 
                            onClick={() => setWatermarkAction('upscale')}
                            className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'upscale' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}
                          >
                            <Zap className="w-8 h-8" />
                            <div className="text-center">
                              <span className="text-xs font-bold block">Upscale</span>
                              <span className="text-[10px] opacity-60">Pertajam Kualitas</span>
                            </div>
                          </button>
                        </div>
                      </div>
                    ) : (
                      <label className="block">
