export interface SocialPlatform {
  id: string;
  name: string;
  ratio: AspectRatio;
  description: string;
}

export const SOCIAL_PLATFORMS: SocialPlatform[] = [
  { id: 'ig_post', name: 'Instagram Post', ratio: AspectRatio.SQUARE, description: 'Persegi (1:1)' },
  { id: 'ig_story', name: 'TikTok / Reels / Story', ratio: AspectRatio.PORTRAIT, description: 'Vertikal (9:16)' },
  { id: 'yt_thumb', name: 'YouTube / Desktop', ratio: AspectRatio.LANDSCAPE, description: 'Layar Lebar (16:9)' },
  { id: 'fb_post', name: 'Facebook Post', ratio: AspectRatio.FOUR_THREE, description: 'Standar (4:3)' },
  { id: 'portrait', name: 'Portrait Classic', ratio: AspectRatio.THREE_FOUR, description: 'Potret (3:4)' }
];

import { GoogleGenAI } from "@google/genai";
import { AspectRatio } from "../types";

const getAI = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateImage = async (
  prompt: string, 
  aspectRatio: AspectRatio = AspectRatio.SQUARE
): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mendapatkan gambar dari AI");
};

export const editImage = async (
  base64Image: string,
  instruction: string,
  aspectRatio?: AspectRatio,
  mimeType: string = 'image/png'
): Promise<string> => {
  const ai = getAI();

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        { text: instruction },
      ],
    },
    config: aspectRatio ? {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mengedit gambar");
};

export const createCollage = async (
  base64Images: string[],
  instruction: string = "Create a stylish and artistic photo collage using these 4 images."
): Promise<string> => {
  const ai = getAI();
  const parts: any[] = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/png'
    }
  }));

  parts.push({ text: instruction });

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal membuat kolase");
};

import React, { useState, useRef } from 'react';
import Sidebar from './components/Sidebar';
import FeatureCard from './components/FeatureCard';
import ImageDisplay from './components/ImageDisplay';
