  };

  return (
    <div className="min-h-screen bg-gray-50 flex text-gray-900">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
      )}

      <Sidebar currentView={currentView} onNavigate={handleNavigate} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="lg:hidden bg-white border-b border-gray-100 p-4 sticky top-0 z-30 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Sparkles className="w-5 h-5" />
            </div>
            <span className="font-bold text-gray-900 tracking-tight">KreativAI</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
            <Menu className="w-6 h-6 text-gray-700" />
          </button>
        </div>

        <div className="p-4 lg:p-8">
          <header className="mb-10 max-w-6xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest mb-2">
                <Sparkles className="w-4 h-4" />
                Gemini KreativAI v2.5
              </div>
              <h1 className="text-3xl lg:text-5xl font-extrabold text-gray-900 tracking-tight">
                {currentView === 'home' ? 'Pusat Kreativitas AI' : FEATURES.find(f => f.id === currentView)?.title}
              </h1>
              <p className="text-gray-500 mt-3 text-base lg:text-lg max-w-xl leading-relaxed">
                {FEATURES.find(f => f.id === currentView)?.description}
              </p>
            </div>
            {currentView !== 'home' && (
              <button onClick={() => handleNavigate('home')} className="text-gray-500 hover:text-gray-900 font-semibold flex items-center gap-2 transition-colors px-4 py-2 bg-white rounded-xl border border-gray-200 shadow-sm">
                Menu Utama
              </button>
            )}
          </header>

          {currentView === 'home' ? (
            <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-20">
              {FEATURES.map((feature) => (
                <FeatureCard key={feature.id} feature={feature} onClick={() => handleNavigate(feature.id)} />
              ))}
            </div>
          ) : (
            <div className="max-w-6xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-10">
              <div className="xl:col-span-7 space-y-8">
                <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-6 lg:p-8">

                  {isCollageView ? (
