                            <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="Contoh: Latar belakang studio futuristik dengan lampu neon biru dan oranye, bokeh di kejauhan..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32 transition-all" />
                          </label>
