                        </div>
                      ) : (
                        <label className="block">
                          <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">{currentView === 'remove-object' ? 'Objek yang ingin dihapus' : 'Instruksi Tambahan'}</span>
                          <textarea value={instruction} onChange={(e) => setInstruction(e.target.value)} placeholder={currentView === 'remove-object' ? "Contoh: Orang di belakang, tiang listrik, tong sampah..." : "Detail tambahan untuk AI..."} className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32" />
                        </label>
                      )}

                      <button onClick={handleEdit} disabled={loading || !uploadedImage} className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all">
                        <Wand2 className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                        {loading ? 'Memproses Gambar...' : (currentView === 'resize' ? 'Mulai Resize AI' : 'Mulai Proses AI')}
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {currentView === 'thumbnail' ? (
                        <>
                          <label className="block">
                            <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Topik / Judul Video</span>
                            <input type="text" value={brandName} onChange={(e) => setBrandName(e.target.value)} placeholder="Contoh: Cara Cepat Belajar AI dalam 10 Menit" className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                          </label>
                          <div className="block">
                            <div className="flex items-center justify-between mb-3">
                              <span className="text-sm font-bold text-gray-900 uppercase tracking-wider">Deskripsi Desain Background</span>
                              <button 
                                onClick={handleSuggestPrompt}
                                disabled={suggestingPrompt || !brandName}
                                className="flex items-center gap-2 text-[10px] font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 hover:bg-blue-100 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                              >
                                {suggestingPrompt ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Stars className="w-3 h-3" />}
                                {suggestingPrompt ? 'Merancang...' : 'Bantu dengan AI'}
                              </button>
                            </div>
                            <textarea 
                              value={prompt} 
                              onChange={(e) => setPrompt(e.target.value)} 
                              placeholder={suggestingPrompt ? "AI sedang merancang deskripsi terbaik untuk Anda..." : "Contoh: Latar belakang studio futuristik dengan lampu neon biru dan oranye, bokeh di kejauhan..."} 
                              className={`w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32 transition-all ${suggestingPrompt ? 'opacity-50 animate-pulse' : ''}`} 
                            />
                          </div>
                        </>
                      ) : (
                        <>
                          {currentView === 'logo' && (
                            <label className="block">
                              <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Teks Brand / Judul</span>
                              <input type="text" value={brandName} onChange={(e) => setBrandName(e.target.value)} placeholder="Nama yang akan ditampilkan di hasil..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none" />
                            </label>
                          )}
                          <label className="block">
                            <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Deskripsi Gambar (Prompt)</span>
                            <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="Contoh: Kucing astronot di bulan, gaya artistik digital..." className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 focus:ring-2 focus:ring-blue-500 outline-none h-32" />
                          </label>
                        </>
                      )}

                      <div className="grid grid-cols-2 gap-6">
                        <div className="space-y-3">
                           <span className="text-sm font-bold text-gray-900 block uppercase tracking-wider">Gaya Visual</span>
                           <select value={style} onChange={(e) => setStyle(e.target.value as ImageStyle)} className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 outline-none">
                              {Object.values(ImageStyle).map(s => <option key={s} value={s}>{s}</option>)}
                           </select>
                        </div>
                        <div className="space-y-3">
                           <span className="text-sm font-bold text-gray-900 block uppercase tracking-wider">Ukuran</span>
                           <select value={ratio} onChange={(e) => setRatio(e.target.value as AspectRatio)} className="w-full bg-gray-50 border border-gray-200 rounded-2xl p-4 outline-none">
                              <option value={AspectRatio.SQUARE}>Persegi (1:1)</option>
                              <option value={AspectRatio.LANDSCAPE}>Landscape (16:9)</option>
                              <option value={AspectRatio.PORTRAIT}>Portrait (9:16)</option>
                           </select>
                        </div>
                      </div>

                      <button onClick={handleGenerate} disabled={loading || (!prompt && !brandName)} className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95 transition-all">
                        <Sparkles className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                        {loading ? 'AI Sedang Merancang...' : (currentView === 'thumbnail' ? 'Buat Thumbnail' : 'Hasilkan Gambar')}
                      </button>
                    </div>
                  )}
                  {error && <div className="mt-4 p-4 bg-red-50 text-red-600 rounded-xl text-sm font-medium border border-red-100">{error}</div>}
                </div>
              </div>
              <div className="xl:col-span-5">
                <ImageDisplay url={resultImage || ''} loading={loading} onRefresh={isEditorView ? handleEdit : handleGenerate} />
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import Sidebar from './components/Sidebar';
import FeatureCard from './components/FeatureCard';
import ImageDisplay from './components/ImageDisplay';
import { AppView, ImageStyle, AspectRatio } from './types';
import { FEATURES, SOCIAL_PLATFORMS } from './constants';
import { generateImage, editImage, suggestThumbnailPrompt } from './services/geminiService';
// Added missing RefreshCw icon import
import { Sparkles, Upload, Wand2, Plus, LayoutGrid, Info, Eraser, Zap, ShieldAlert, Menu, Instagram, Tv, Facebook, Smartphone, Image as ImageIcon, Stars, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [suggestingPrompt, setSuggestingPrompt] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ImageStyle>(ImageStyle.REALISTIC);
  const [ratio, setRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [brandName, setBrandName] = useState('');
  const [instruction, setInstruction] = useState('');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const [collageImages, setCollageImages] = useState<(string | null)[]>([null, null, null, null]);
  const [watermarkAction, setWatermarkAction] = useState<'remove_text' | 'remove_logo' | 'upscale'>('remove_text');
  const [selectedPlatform, setSelectedPlatform] = useState(SOCIAL_PLATFORMS[0].id);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const collageInputRefs = [useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null), useRef<HTMLInputElement>(null)];

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setUploadedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCollageUpload = (index: number, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newImages = [...collageImages];
        newImages[index] = reader.result as string;
        setCollageImages(newImages);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSuggestPrompt = async () => {
    if (!brandName) {
      setError("Masukkan judul video terlebih dahulu agar AI bisa memberikan saran.");
      return;
    }
    setSuggestingPrompt(true);
    setError(null);
    try {
      const suggested = await suggestThumbnailPrompt(brandName);
      setPrompt(suggested);
    } catch (err) {
      setError("Gagal mendapatkan saran AI. Silakan coba lagi.");
    } finally {
      setSuggestingPrompt(false);
    }
  };

  const resetState = () => {
    setResultImage(null);
    setPrompt('');
    setInstruction('');
    setUploadedImage(null);
    setCollageImages([null, null, null, null]);
    setWatermarkAction('remove_text');
    setBrandName('');
    setError(null);
    setSuggestingPrompt(false);
  };

  const handleNavigate = (view: AppView) => {
    setCurrentView(view);
    setIsSidebarOpen(false);
    resetState();
    if (view === 'thumbnail') {
      setRatio(AspectRatio.LANDSCAPE);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      let finalPrompt = prompt;
      if (currentView === 'logo') {
        finalPrompt = `Professional vector logo for "${brandName}". Clean, high resolution. Style: ${style}. ${prompt}`;
      } else if (currentView === 'mascot') {
        finalPrompt = `Character mascot. Style: ${style}. Isolated on white. ${prompt}`;
      } else if (currentView === 'thumbnail') {
        finalPrompt = `Stunning YouTube thumbnail for a video titled "${brandName}". Background design: ${prompt}. High contrast, eye-catching text, style: ${style}.`;
      } else {
        finalPrompt = `${prompt}, ${style} style.`;
      }

      const url = await generateImage(finalPrompt, ratio);
      setResultImage(url);
    } catch (err: any) {
      setError(err.message || "Gagal memproses permintaan.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!uploadedImage) return;
    setLoading(true);
    setError(null);
    try {
      let editInstruction = instruction;
      let targetRatio: AspectRatio | undefined = undefined;

      if (currentView === 'resize') {
        const platform = SOCIAL_PLATFORMS.find(p => p.id === selectedPlatform);
        targetRatio = platform?.ratio;
        editInstruction = `This is a professional image expansion (outpainting) task. Expand and fill the background of this image to perfectly fit a ${platform?.name} format with an aspect ratio of ${platform?.ratio}. Maintain the central subject's integrity and quality while realistically extending the surroundings.`;
      } else if (currentView === 'watermark') {
        switch(watermarkAction) {
          case 'remove_text':
            editInstruction = `Remove all text watermarks and lettering from this image. Carefully inpaint the background to look original and clean.`;
            break;
          case 'remove_logo':
            editInstruction = `Detect and remove any logo watermarks or branding icons from this image. Fill the background space naturally.`;
            break;
          case 'upscale':
            editInstruction = `Sharpen this image, enhance details, and increase clarity. Reduce noise and make it look professional and high resolution.`;
            break;
        }
      } else if (currentView === 'remove-object') {
        editInstruction = `Remove the object: "${instruction}" from this photo. Use seamless inpainting to fill the background.`;
      } else if (currentView === 'graduation') {
        editInstruction = `Add a professional graduation toga and cap to the person in this photo. White/Studio background. ${instruction}`;
      } else if (currentView === 'age') {
        editInstruction = `Change the person's age: ${instruction}. Maintain facial structure and realism.`;
      }

      const url = await editImage(uploadedImage, editInstruction, targetRatio);
      setResultImage(url);
    } catch (err: any) {
      setError("Ups! Gagal memproses gambar. Pastikan kualitas foto cukup baik.");
    } finally {
      setLoading(false);
    }
  };

  const handleCollage = async () => {
    setLoading(true);
    setError(null);
    try {
      const validImages = collageImages.filter(img => img !== null) as string[];
      if (validImages.length < 2) throw new Error("Unggah minimal 2 gambar untuk kolase.");

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const size = 2000;
      const spacing = 40;
      const halfSize = (size - spacing) / 2;
      canvas.width = size;
      canvas.height = size;
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, size, size);

      const positions = [{ x: 0, y: 0 }, { x: halfSize + spacing, y: 0 }, { x: 0, y: halfSize + spacing }, { x: halfSize + spacing, y: halfSize + spacing }];

      const loadAndDraw = (src: string, pos: {x: number, y: number}) => {
        return new Promise<void>((resolve) => {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.onload = () => {
            const imgRatio = img.width / img.height;
            let drawW, drawH, offsetLeft, offsetTop;
            if (imgRatio > 1) {
              drawH = halfSize; drawW = halfSize * imgRatio;
              offsetLeft = (drawW - halfSize) / 2; offsetTop = 0;
            } else {
              drawW = halfSize; drawH = halfSize / imgRatio;
              offsetLeft = 0; offsetTop = (drawH - halfSize) / 2;
            }
            ctx.save();
            ctx.beginPath();
            ctx.roundRect(pos.x, pos.y, halfSize, halfSize, 40);
            ctx.clip();
            ctx.drawImage(img, pos.x - offsetLeft, pos.y - offsetTop, drawW, drawH);
            ctx.restore();
            resolve();
          };
          img.src = src;
        });
      };

      for (let i = 0; i < validImages.length; i++) {
        await loadAndDraw(validImages[i], positions[i]);
      }

      setResultImage(canvas.toDataURL('image/png'));
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const isEditorView = ['resize', 'graduation', 'age', 'remove-object', 'watermark'].includes(currentView);
  const isCollageView = currentView === 'collage';

  const getPlatformIcon = (id: string) => {
    switch(id) {
      case 'ig_post': return <Instagram className="w-5 h-5" />;
      case 'ig_story': return <Smartphone className="w-5 h-5" />;
      case 'yt_thumb': return <Tv className="w-5 h-5" />;
      case 'fb_post': return <Facebook className="w-5 h-5" />;
      default: return <ImageIcon className="w-5 h-5" />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex text-gray-900">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
      )}

      <Sidebar currentView={currentView} onNavigate={handleNavigate} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="lg:hidden bg-white border-b border-gray-100 p-4 sticky top-0 z-30 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
              <Sparkles className="w-5 h-5" />
            </div>
            <span className="font-bold text-gray-900 tracking-tight">KreativAI</span>
          </div>
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
            <Menu className="w-6 h-6 text-gray-700" />
          </button>
        </div>

        <div className="p-4 lg:p-8">
          <header className="mb-10 max-w-6xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <div className="flex items-center gap-2 text-blue-600 font-bold text-sm uppercase tracking-widest mb-2">
                <Sparkles className="w-4 h-4" />
                Gemini KreativAI v2.5
              </div>
              <h1 className="text-3xl lg:text-5xl font-extrabold text-gray-900 tracking-tight">
                {currentView === 'home' ? 'Pusat Kreativitas AI' : FEATURES.find(f => f.id === currentView)?.title}
              </h1>
              <p className="text-gray-500 mt-3 text-base lg:text-lg max-w-xl leading-relaxed">
                {FEATURES.find(f => f.id === currentView)?.description}
              </p>
            </div>
            {currentView !== 'home' && (
              <button onClick={() => handleNavigate('home')} className="text-gray-500 hover:text-gray-900 font-semibold flex items-center gap-2 transition-colors px-4 py-2 bg-white rounded-xl border border-gray-200 shadow-sm">
                Menu Utama
              </button>
            )}
          </header>

          {currentView === 'home' ? (
            <div className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-20">
              {FEATURES.map((feature) => (
                <FeatureCard key={feature.id} feature={feature} onClick={() => handleNavigate(feature.id)} />
              ))}
            </div>
          ) : (
            <div className="max-w-6xl mx-auto grid grid-cols-1 xl:grid-cols-12 gap-10">
              <div className="xl:col-span-7 space-y-8">
                <div className="bg-white rounded-3xl border border-gray-100 shadow-sm p-6 lg:p-8">

                  {isCollageView ? (
                    <div className="space-y-6">
                      <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex gap-3 text-blue-700 text-sm">
                        <Info className="w-5 h-5 shrink-0" />
                        <p>Gabungkan hingga 4 foto secara instan. Hasil akan mempertahankan kualitas asli foto Anda tanpa distorsi AI.</p>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        {collageImages.map((img, idx) => (
                          <div key={idx} onClick={() => collageInputRefs[idx].current?.click()} className="aspect-square border-2 border-dashed border-gray-200 rounded-2xl flex items-center justify-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all overflow-hidden relative">
                            {img ? <img src={img} className="w-full h-full object-cover" alt="Preview" /> : (
                              <div className="flex flex-col items-center gap-2 text-gray-400">
                                <Plus className="w-8 h-8" />
                                <span className="text-xs font-bold">Slot {idx + 1}</span>
                              </div>
                            )}
                            <input type="file" ref={collageInputRefs[idx]} onChange={(e) => handleCollageUpload(idx, e)} className="hidden" accept="image/*" />
                          </div>
                        ))}
                      </div>
                      <button onClick={handleCollage} disabled={loading || collageImages.filter(i => i).length < 2} className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg active:scale-95">
                        <LayoutGrid className={`w-6 h-6 ${loading ? 'animate-spin' : ''}`} />
                        {loading ? 'Menyusun Kolase...' : 'Gabungkan Sekarang'}
                      </button>
                    </div>
                  ) : isEditorView ? (
                    <div className="space-y-6">
                      <label className="block">
                        <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Unggah Foto Utama</span>
                        <div onClick={() => fileInputRef.current?.click()} className="border-2 border-dashed border-gray-200 rounded-2xl p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all">
                          {uploadedImage ? (
                            <div className="relative inline-block">
                              <img src={uploadedImage} alt="Uploaded" className="max-h-64 rounded-xl shadow-lg" />
                              <div className="absolute -top-2 -right-2 bg-blue-600 text-white p-1.5 rounded-full shadow-lg"><Upload className="w-4 h-4" /></div>
                            </div>
                          ) : (
                            <div className="flex flex-col items-center gap-4 py-4">
                              <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400">
                                <Upload className="w-8 h-8" />
                              </div>
                              <p className="font-bold text-gray-900">Ketuk untuk pilih foto</p>
                            </div>
                          )}
                          <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                        </div>
                      </label>

                      {currentView === 'resize' ? (
                        <div className="space-y-6">
                          <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Pilih Ukuran Platform</span>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {SOCIAL_PLATFORMS.map((platform) => (
                              <button
                                key={platform.id}
                                onClick={() => setSelectedPlatform(platform.id)}
                                className={`p-4 rounded-2xl border text-left flex items-center gap-4 transition-all ${selectedPlatform === platform.id ? 'border-blue-600 bg-blue-50 shadow-md ring-2 ring-blue-600/20' : 'border-gray-200 hover:border-blue-300 bg-white'}`}
                              >
                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${selectedPlatform === platform.id ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-500'}`}>
                                  {getPlatformIcon(platform.id)}
                                </div>
                                <div className="flex-1">
                                  <div className={`text-sm font-bold ${selectedPlatform === platform.id ? 'text-blue-700' : 'text-gray-900'}`}>{platform.name}</div>
                                  <div className="text-[10px] text-gray-500 font-medium">{platform.description}</div>
                                </div>
                              </button>
                            ))}
                          </div>
                          <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex gap-3 text-amber-800 text-xs">
                            <Zap className="w-4 h-4 shrink-0" />
                            <p>AI akan otomatis memperluas latar belakang gambar Anda untuk mengisi dimensi platform yang dipilih (Outpainting).</p>
                          </div>
                        </div>
                      ) : currentView === 'watermark' ? (
                        <div className="space-y-6">
                          <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">Pilih Alat Pembersih</span>
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <button onClick={() => setWatermarkAction('remove_text')} className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'remove_text' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}>
                              <Eraser className="w-8 h-8" />
                              <div className="text-center">
                                <span className="text-xs font-bold block">Hapus Teks</span>
                                <span className="text-[10px] opacity-60">Watermark Tulisan</span>
                              </div>
                            </button>
                            <button onClick={() => setWatermarkAction('remove_logo')} className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'remove_logo' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}>
                              <ShieldAlert className="w-8 h-8" />
                              <div className="text-center">
                                <span className="text-xs font-bold block">Hapus Logo</span>
                                <span className="text-[10px] opacity-60">Ikon / Branding</span>
                              </div>
                            </button>
                            <button onClick={() => setWatermarkAction('upscale')} className={`p-6 rounded-2xl border flex flex-col items-center gap-3 transition-all ${watermarkAction === 'upscale' ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md' : 'border-gray-200 hover:border-blue-300'}`}>
                              <Zap className="w-8 h-8" />
                              <div className="text-center">
                                <span className="text-xs font-bold block">Upscale</span>
                                <span className="text-[10px] opacity-60">Pertajam Kualitas</span>
                              </div>
                            </button>
                          </div>
                        </div>
                      ) : (
                        <label className="block">
                          <span className="text-sm font-bold text-gray-900 block mb-3 uppercase tracking-wider">{currentView === 'remove-object' ? 'Objek yang ingin dihapus' : 'Instruksi Tambahan'}</span>
