import { GoogleGenAI } from "@google/genai";
import { AspectRatio } from "../types";

const getAI = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Menghasilkan deskripsi background thumbnail yang sangat relevan dengan judul video.
 * Menggunakan strategi visual storytelling untuk menarik perhatian audiens.
 */
export const suggestThumbnailPrompt = async (videoTitle: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `You are a professional YouTube Thumbnail Creative Director. 
    Analyze this video title: "${videoTitle}".

    Task: Create a vivid, high-impact image generation prompt for a background that perfectly matches the core topic and emotion of this title.

    Guidelines:
    1. Identify the niche: (e.g., Tech, Finance, Lifestyle, Horror, Gaming).
    2. Suggest a background that acts as a visual metaphor for the title.
    3. Use professional photography terms: "cinematic lighting", "rim light", "bokeh background", "extremely detailed", "vibrant colors", "8k resolution".
    4. Ensure the background is clean and provides good space for text overlay (which will be added later).
    5. ABSOLUTELY NO TEXT within the generated image background.
    6. Language: Output MUST be in English for better AI image generation results.
    7. Output format: Provide ONLY the prompt text. No "Here is your prompt" or quotes.`,
  });

  return response.text.trim();
};

export const generateImage = async (
  prompt: string, 
  aspectRatio: AspectRatio = AspectRatio.SQUARE
): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: prompt }]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mendapatkan gambar dari AI");
};

export const editImage = async (
  base64Image: string,
  instruction: string,
  aspectRatio?: AspectRatio,
  mimeType: string = 'image/png'
): Promise<string> => {
  const ai = getAI();

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        { text: instruction },
      ],
    },
    config: aspectRatio ? {
      imageConfig: {
        aspectRatio: aspectRatio
      }
    } : undefined
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal mengedit gambar");
};

export const createCollage = async (
  base64Images: string[],
  instruction: string = "Create a stylish and artistic photo collage using these 4 images."
): Promise<string> => {
  const ai = getAI();
  const parts: any[] = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/png'
    }
  }));

  parts.push({ text: instruction });

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }

  throw new Error("Gagal membuat kolase");
};

